// Two synthetic fixtures, two calls maximum, no retries or persisted credentials.
import assert from 'node:assert/strict';
import { createRequire } from 'node:module';
import { resolve, join } from 'node:path';
import { mkdir, writeFile } from 'node:fs/promises';
import { createHash } from 'node:crypto';
const root = process.cwd();
const require = createRequire(join(root, 'package.json'));
const { build } = require('esbuild');
const output = resolve(process.env.PHOTO_EVAL_OUTPUT || 'artifacts/material-contents-photo-smoke');
await mkdir(output, { recursive: true });
const result = await build({ stdin: { contents: `export * from './shared/materialContentsPhoto'; export { resolveChatModel } from './workers/ai-proxy/src/modelPolicy'; export { resolveOpenAiChatTemperature } from './shared/aiProxyContract';`, resolveDir: root }, bundle: true, write: false, platform: 'node', format: 'esm', logLevel: 'silent' });
const contract = await import('data:text/javascript;base64,' + Buffer.from(result.outputFiles[0].text).toString('base64'));
const { MATERIAL_CONTENTS_PHOTO_PROMPT: prompt, MATERIAL_CONTENTS_PHOTO_RESPONSE_FORMAT: format, parseMaterialContentsPhotoResult: parse } = contract;
const { model } = contract.resolveChatModel({ purpose: 'weekly_planning_attachment' });
assert.equal(model, 'gpt-6-luna', 'Unexpected model; stop rather than broaden authorization.');
const temperature = contract.resolveOpenAiChatTemperature(model, 0);
const row = (title, level, startPage) => ({ title, level, startPage, endPage: null });
const cases = [
  { id: 'clear-hierarchy', expected: [row('第1章 数の基礎', 1, 3), row('1.1 数の表し方', 2, 5), row('1.1.1 整数', 3, 7), row('1.2 図形', 2, 12), row('第2章 規則性', 1, 20), row('2.1 数列', 2, 23)] },
  { id: 'redacted-page', expected: [row('Chapter 3 Review', 1, 30), row('3.1 Recall', 2, null), row('3.2 Practice', 2, 40)] },
];
const fixturePngs = {"clear-hierarchy": "", "redacted-page": ""};
const report = { schema: 'material-contents-photo-live-smoke-v1', provider: 'OpenAI', model, requestedCalls: 2, actualCalls: 0, maxCompletionTokensPerCall: 8000, productionUserData: false, head: process.env.PHOTO_EVAL_SOURCE_SHA || null, scope: 'Exact production prompt/schema/model; provider-only smoke. Does not prove deployed auth/quota/UI.', cases: [], status: 'running' };
async function save() { await writeFile(join(output, 'report.json'), JSON.stringify(report, null, 2)); }
const dryRun = process.argv.includes('--prepare-only');
const key = process.env.OPENAI_API_KEY?.trim();
if (!dryRun && !key) { report.status = 'blocked_missing_existing_secret'; await save(); process.exit(2); }
for (const test of cases) {
  const image = Buffer.from(fixturePngs[test.id], 'base64');
  await writeFile(join(output, `${test.id}.png`), image);
  const record = { id: test.id, fixtureSha256: createHash('sha256').update(image).digest('hex'), expected: test.expected };
  report.cases.push(record);
  if (dryRun) continue;
  try {
    report.actualCalls++;
    const response = await fetch('https://api.openai.com/v1/chat/completions', {
      method: 'POST', redirect: 'manual', signal: AbortSignal.timeout(120000),
      headers: { 'Content-Type': 'application/json', Authorization: `Bearer ${key}` },
      body: JSON.stringify({ model, ...(temperature === undefined ? {} : { temperature }), messages: [
        { role: 'system', content: prompt },
        { role: 'user', content: [{ type: 'text', text: 'この教材の目次を読み取ってください。' }, { type: 'image_url', image_url: { url: `data:image/png;base64,${image.toString('base64')}`, detail: 'high' } }] },
      ], response_format: format, max_completion_tokens: 8000 }),
    });
    record.httpStatus = response.status;
    if (!response.ok) { record.status = 'provider_http_error'; report.status = 'blocked_provider'; await save(); process.exit(2); }
    const data = await response.json();
    record.usage = data.usage;
    const parsed = parse(JSON.parse(data.choices?.[0]?.message?.content || 'null'));
    record.validSchema = parsed !== null;
    record.extracted = parsed?.items ?? null;
    record.exactHierarchyAndTitles = JSON.stringify(parsed?.items.map(({ title, level }) => ({ title, level }))) === JSON.stringify(test.expected.map(({ title, level }) => ({ title, level })));
    record.exactVisiblePagesAndNulls = JSON.stringify(parsed?.items) === JSON.stringify(test.expected);
    record.noInventedEndPages = Boolean(parsed?.items.every(item => item.endPage === null));
    record.status = record.validSchema && record.exactHierarchyAndTitles && record.exactVisiblePagesAndNulls && record.noInventedEndPages ? 'pass' : 'fail';
    await save();
  } catch {
    record.status = 'transport_or_parse_error'; report.status = 'blocked_or_invalid_response'; await save(); process.exit(2);
  }
}
report.status = dryRun ? 'prepared_only_no_api_calls' : report.cases.every(item => item.status === 'pass') ? 'pass' : 'fail';
await save();
console.log(JSON.stringify({ provider: report.provider, model, actualCalls: report.actualCalls, status: report.status }));
if (report.status === 'fail') process.exitCode = 1;
